async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }
  return (await response.json()) as T;
}

async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return await Promise.all(ids.map((id) => loadUser(id)));
}

