export interface Org {
  id?: string;
  name?: string;
  [key: string]: unknown;
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Request failed with status ${res.status} for ${url}`);
  }
  return (await res.json()) as T;
}

export async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

export async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

- `Rc<RefCell<T>>`: single-threaded shared ownership + interior mutability. Cheap, but not `Send`/`Sync`; borrow rules enforced at runtime (`RefCell` can panic). Use for UI/local graphs/caches in one thread.
- `Arc<Mutex<T>>`: thread-safe shared ownership + exclusive locking. Atomic refcount, `Send`/`Sync` if `T: Send`; use across threads. Locking can block/deadlock.

```rust
// Rc<RefCell<T>>
use std::rc::Rc;
use std::cell::RefCell;

let shared = Rc::new(RefCell::new(5));
*shared.borrow_mut() += 1;

// Arc<Mutex<T>>
use std::sync::{Arc, Mutex};
use std::thread;

let shared = Arc::new(Mutex::new(5));
let s = shared.clone();
thread::spawn(move || {
    *s.lock().unwrap() += 1;
});
```

Rule of thumb: single-threaded → `Rc<RefCell<T>>`; multi-threaded → `Arc<Mutex<T>>`.

- `Rc<RefCell<T>>`: single-threaded shared ownership + interior mutability. Cheap, but not `Send`/`Sync`; use only within one thread. `RefCell` enforces borrow rules at runtime and can panic on conflicting borrows.
- `Arc<Mutex<T>>`: thread-safe shared ownership + mutual exclusion. Use when data is shared across threads. `Arc` is atomic refcounting; `Mutex` serializes access and can block/deadlock.

Single-threaded:
```rust
use std::rc::Rc;
use std::cell::RefCell;

let data = Rc::new(RefCell::new(5));
*data.borrow_mut() += 1;
println!("{}", data.borrow());
```

Multi-threaded:
```rust
use std::sync::{Arc, Mutex};
use std::thread;

let data = Arc::new(Mutex::new(5));
let d = Arc::clone(&data);
thread::spawn(move || {
    *d.lock().unwrap() += 1;
});
thread::sleep(std::time::Duration::from_millis(10));
println!("{}", *data.lock().unwrap());
```

Rule of thumb: `Rc<RefCell<T>>` for one thread; `Arc<Mutex<T>>` for shared state across threads.
